self.custom.loading = True
self.custom.errorMessage = ''
self.custom.warningMessage = ''
self.custom.result = None
self.custom.actualQtyKg = None
try:
	params = self.params.value or {}
	order = params.get('order') or {}
	workOrderId = params.get('workOrderId') or order.get('workOrderId')
	self.custom.scheduledStart = params.get('scheduledStart')
	self.custom.orderNotes = params.get('orderNotes')
	if not order and workOrderId is not None:
		orderResult = kanoaScripts.custom.ops.receiving.getReceivingOrder(workOrderId)
		if orderResult.get('status') == 'SUCCESS':
			order = orderResult.get('data', {}).get('order', {})
		else:
			self.custom.errorMessage = orderResult.get('message', 'Order is not eligible.')
	self.custom.order = order
	if workOrderId is None:
		self.custom.errorMessage = 'No eligible order was selected. Return to the schedule and select an order.'
		return
	if not self.custom.orderNotes:
		try:
			orderRows = system.kanoa.order.getProductionOrders({'workOrderId': workOrderId, 'ignoreActualQty': True})
			self.custom.orderNotes = system.kanoa.utilities.getFieldValue('note', orderRows)
		except Exception as notesExc:
			kanoaScripts.custom.ops.receiving.getLogger().error('Receive Material notes load failed: %s' % str(notesExc))
	self.custom.notesDraft = self.custom.orderNotes or ''
	orderUnit = (self.custom.order or {}).get('unitName')
	self.custom.unitName = orderUnit
	if not orderUnit and (self.custom.order or {}).get('workOrderId') is not None:
		self.custom.errorMessage = 'This order has no unit of measure. Ask a supervisor to correct the order.'
	unitOptions = []
	try:
		unitRows = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.item.getItemUnits({'enabled': True}))
		unitOptions = [{'label': row.get('itemUnitName'), 'value': row.get('itemUnitName')} for row in unitRows if row.get('itemUnitName')]
	except Exception as unitsExc:
		kanoaScripts.custom.ops.receiving.getLogger().warn('Receive Material unit list load failed: %s' % str(unitsExc))
	if orderUnit and orderUnit not in [option['value'] for option in unitOptions]:
		unitOptions.insert(0, {'label': orderUnit, 'value': orderUnit})
	self.custom.unitOptions = unitOptions
	assetsResult = kanoaScripts.custom.ops.receiving.getReceivingAssets()
	if assetsResult.get('status') == 'SUCCESS':
		assets = assetsResult.get('data', {})
		self.custom.truckOptions = [{'label': a.get('assetPath') or a.get('assetName'), 'value': a.get('assetId')} for a in assets.get('trucks', [])]
		self.custom.tankOptions = [{'label': a.get('assetPath') or a.get('assetName'), 'value': a.get('assetId')} for a in assets.get('tanks', [])]
	else:
		self.custom.errorMessage = assetsResult.get('message', 'Receiving assets could not be loaded.')
	qtyResult = kanoaScripts.custom.ops.receiving.getReceivedQtyForOrder(workOrderId)
	if qtyResult.get('status') == 'SUCCESS':
		self.custom.receivedQtyKg = qtyResult.get('data', {}).get('receivedQtyKg', 0)
		try:
			targetQty = float(self.custom.order.get('targetQty'))
		except (TypeError, ValueError):
			targetQty = None
		if targetQty is not None and targetQty > 0:
			remaining = max(0, targetQty - float(self.custom.receivedQtyKg or 0))
			self.custom.actualQtyKg = remaining
			if remaining <= 0:
				self.custom.errorMessage = 'This order is fully received. No further receipt can be recorded.'
		else:
			self.custom.errorMessage = 'The order target quantity is unavailable or not greater than zero. Receiving is blocked until a supervisor corrects the order.'
	else:
		self.custom.receivedQtyKg = None
		self.custom.errorMessage = qtyResult.get('message', 'Receipt history could not be loaded. Do not retry until the order is reconciled.')
except Exception as exc:
	kanoaScripts.custom.ops.receiving.getLogger().error('Receive Material startup failed: %s' % str(exc))
	self.custom.errorMessage = 'Could not load the selected order or receiving data. Return to the schedule or contact a supervisor.'
finally:
	self.custom.loading = False

